export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = 9.8;
  const height = launchSpeed * time - 0.5 * gravity * time * time;
  const velocity = launchSpeed - gravity * time;
  const maxH = (launchSpeed * launchSpeed) / (2 * gravity);
  const displayH = Math.max(0, Math.min(maxH * 1.3, maxH * 1.2 + 0.5));
  const scaleY = (y) => 350 - (y / Math.max(1, displayH)) * 260;

  const ballY = scaleY(Math.max(0, height));
  const ballX = 320;

  const objects = [];

  objects.push(sdk.panel({x: 40, y: 40, w: 560, h: 360, title: "Vertical Toss", state: `Time: ${sdk.format(time, 2)} s`}));
  objects.push(sdk.axis("axis.height", {x: 120, y: 320, length: 260, orientation: "y", min: 0, max: Math.max(1, Math.ceil(displayH * 10) / 10), ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m"}));
  objects.push(sdk.groundMark("mark.launch", ballX, scaleY(0), 60, "Launch"));

  objects.push(sdk.circle("ball.toss", ballX, ballY, 28, {role: "output"}));

  const vMag = Math.abs(velocity);
  const vDir = velocity > 0 ? "up" : (velocity < 0 ? "down" : "up");
  if (vMag > 0.05) {
    objects.push(sdk.vector("vec.v", {x: ballX + 20, y: ballY}, {value: vMag, direction: vDir}, {scale: 15, minLength: 12, label: "v"}));
  }
  objects.push(sdk.vector("vec.a", {x: ballX - 20, y: ballY}, {value: gravity, direction: "down"}, {scale: 8, minLength: 12, label: "a"}));

  let motionText = "Moving up";
  if (Math.abs(velocity) < 0.08) {
    motionText = "Still for an instant";
  } else if (velocity < 0) {
    motionText = "Moving down";
  }

  const calloutLines = [motionText, "Gravity pulls down"];
  objects.push(sdk.callout(ballX + 45, ballY - 20, calloutLines, {id: "callout.toss"}));

  let motionStateVal = "Moving up";
  if (Math.abs(velocity) < 0.08) {
    motionStateVal = "Still";
  } else if (velocity < 0) {
    motionStateVal = "Moving down";
  }

  return {
    frame: {
      width: 640,
      height: 420,
      objects: objects,
      readouts: [
        { id: "motionState", value: motionStateVal },
        { id: "gravityState", value: "Pulling down" }
      ]
    },
    quantities: {
      launchSpeed: launchSpeed,
      gravity: gravity,
      apexTime: launchSpeed / gravity,
      apexHeight: (launchSpeed * launchSpeed) / (2 * gravity),
      velocity: velocity,
      height: height
    }
  };
}
